import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";
import sorsuLogo from "../assets/sorsu-logo.png";

const API_URL = "http://localhost:5000";

const THEME = {
  primary: "#B11226",
  primaryDark: "#8E0E1E",
  background: "#F8F9FA",
  white: "#FFFFFF",
  textDark: "#1F2937",
  lightGray: "#E5E7EB",
};

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [selected, setSelected] = useState({});
  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(res.data);
      } catch (error) {
        setModalType("error");
        setModalMessage("Failed to load candidates.");
        setShowModal(true);
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  const handleSelect = (position, candidateId) => {
    setSelected((prev) => ({
      ...prev,
      [position]: candidateId,
    }));
  };

  const handleCastVote = () => {
    if (Object.keys(selected).length === 0) {
      setModalType("error");
      setModalMessage("Please select a candidate before casting vote.");
      setShowModal(true);
      return;
    }
    setModalType("confirm");
    setModalMessage("Are you sure you want to cast your vote?");
    setShowModal(true);
  };

  const confirmVote = async () => {
    try {
      setSubmitting(true);
      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds: Object.values(selected) },
        {
          headers: {
            Authorization: `Bearer ${auth?.token}`,
          },
        }
      );
      setModalType("success");
      setModalMessage("Your vote has been successfully recorded.");
      setSelected({});
    } catch (error) {
      setModalType("error");
      setModalMessage("Vote failed or you may have already voted.");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return <div style={{ padding: 50 }}>Loading candidates...</div>;
  }

  return (
    <div style={{ backgroundColor: THEME.background, minHeight: "100vh" }}>

      {/* 🔴 CURVED HEADER */}
      <div
        style={{
          background: `linear-gradient(to right, ${THEME.primary}, ${THEME.primaryDark})`,
          padding: "35px 60px",
          display: "flex",
          alignItems: "center",
          borderBottomLeftRadius: "50px",
          borderBottomRightRadius: "50px",
          boxShadow: "0 12px 30px rgba(0,0,0,0.15)",
        }}
      >
        <img
          src={sorsuLogo}
          alt="SorSU Logo"
          style={{
            height: 80,
            marginRight: 25,
          }}
        />
        <div style={{ color: "white" }}>
          <h2 style={{ margin: 0, fontSize: 26 }}>
            SorSU Online Voting System
          </h2>
          <p style={{ margin: 0, opacity: 0.9 }}>
            Official Student Election Portal 2026
          </p>
        </div>
      </div>

      {/* CONTENT */}
      <div style={{ padding: "80px 60px 60px 60px", maxWidth: 1300, margin: "auto" }}>
        {Object.entries(groupedCandidates).map(([position, list]) => (
          <div key={position} style={{ marginBottom: 60 }}>
            <h2
              style={{
                marginBottom: 30,
                color: THEME.primary,
                borderLeft: `6px solid ${THEME.primary}`,
                paddingLeft: 15,
              }}
            >
              {position}
            </h2>

            <div
              style={{
                display: "flex",
                gap: 30,
                flexWrap: "nowrap",
                overflowX: "auto",
                paddingBottom: 10,
              }}
            >
              {list.map((candidate) => {
                const isSelected = selected[position] === candidate._id;

                return (
                  <div
                    key={candidate._id}
                    onClick={() => handleSelect(position, candidate._id)}
                    style={{
                      width: 220,
                      flex: "0 0 auto",
                      backgroundColor: THEME.white,
                      borderRadius: 18,
                      padding: 20,
                      cursor: "pointer",
                      border: isSelected
                        ? `4px solid ${THEME.primary}`
                        : "2px solid transparent",
                      boxShadow: isSelected
                        ? "0 15px 35px rgba(177,18,38,0.3)"
                        : "0 10px 25px rgba(0,0,0,0.05)",
                      transition: "0.3s",
                    }}
                  >
                    {candidate.image && (
                      <img
                        src={`${API_URL}/uploads/${candidate.image}`}
                        alt=""
                        style={{
                          width: "100%",
                          height: 220,
                          objectFit: "cover",
                          borderRadius: 14,
                          marginBottom: 15,
                        }}
                      />
                    )}
                    <h3>{candidate.firstName} {candidate.lastName}</h3>
                    <p>{candidate.yearLevel} - {candidate.block}</p>
                    <p>Partylist: {candidate.partylist || "Independent"}</p>
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {/* CAST VOTE BUTTON */}
        <div style={{ textAlign: "center", marginTop: 40 }}>
          <button
            onClick={handleCastVote}
            disabled={submitting}
            style={{
              padding: "16px 45px",
              fontSize: 18,
              fontWeight: "bold",
              background: `linear-gradient(to right, ${THEME.primary}, ${THEME.primaryDark})`,
              color: "white",
              border: "none",
              borderRadius: 30,
              cursor: "pointer",
              boxShadow: "0 8px 20px rgba(177,18,38,0.3)",
              transition: "0.3s",
            }}
          >
            {submitting ? "Submitting..." : "Cast Vote"}
          </button>
        </div>
      </div>

      {/* MODAL */}
      {showModal && (
        <div style={modalStyles.overlay}>
          <div style={modalStyles.modal}>
            <h3>
              {modalType === "confirm"
                ? "Confirm Vote"
                : modalType === "success"
                ? "Success"
                : "Error"}
            </h3>
            <p style={{ marginBottom: 20 }}>{modalMessage}</p>

            {modalType === "confirm" ? (
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <button style={modalStyles.cancel} onClick={() => setShowModal(false)}>
                  Cancel
                </button>
                <button style={modalStyles.confirm} onClick={confirmVote}>
                  Confirm
                </button>
              </div>
            ) : (
              <button style={modalStyles.confirm} onClick={() => setShowModal(false)}>
                OK
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const modalStyles = {
  overlay: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    backgroundColor: "rgba(0,0,0,0.6)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    width: 380,
    backgroundColor: "#fff",
    padding: 30,
    borderRadius: 15,
    textAlign: "center",
  },
  cancel: {
    padding: "10px 20px",
    backgroundColor: "#ccc",
    border: "none",
    borderRadius: 8,
    cursor: "pointer",
  },
  confirm: {
    padding: "10px 20px",
    backgroundColor: "#B11226",
    color: "#fff",
    border: "none",
    borderRadius: 8,
    cursor: "pointer",
  },
};

export default VotingPage;
